package com.supportsphere.config; import java.io.*; import java.util.*; public final class AppConfig { private static final Properties P=new Properties(); static { try(InputStream in=AppConfig.class.getResourceAsStream("/application.properties")){ if(in!=null)P.load(in); }catch(Exception e){throw new ExceptionInInitializerError(e);} } public static String get(String k){return P.getProperty(k,"");} private AppConfig(){} }
